def geohash_neighbors_needed(prefix: str) -> int:
    # Must query center + 8 surrounding cells to avoid boundary-seam misses
    return 9

def h3_ring_count(k: int) -> int:
    # Number of hexagons in filled k-ring: 1 + 3*k*(k+1)
    return 1 + 3 * k * (k + 1)

def aggregate_to_parent_res(driver_cells_res9: list[int], h3_lib, target_res: int = 7) -> dict:
    counts = {}
    for cell in driver_cells_res9:
        parent = h3_lib.cell_to_parent(cell, target_res)
        counts[parent] = counts.get(parent, 0) + 1
    return counts

def find_best_drivers(spatial_index, eta_svc, rider_h3: int, rider_loc: tuple) -> list[tuple]:
    candidates = []
    for k in (1, 2, 3):
        for cell in spatial_index.k_ring(rider_h3, k):
            candidates.extend(spatial_index.get_available_drivers(cell))
        if len(candidates) >= 15:
            break
    scored = [(eta_svc.get_eta(d.loc, rider_loc), d) for d in candidates[:50]]
    return sorted(scored, key=lambda x: x[0])

def sample_cell_drivers(drivers: list, max_candidates: int = 50) -> list:
    import random
    if len(drivers) <= max_candidates:
        return drivers
    return random.sample(drivers, max_candidates)

def update_driver_cell(driver_map: dict, cell_index: dict, driver_id: str, new_cell: int, ts_ms: int):
    prev = driver_map.get(driver_id)
    if prev and prev['ts_ms'] >= ts_ms:
        return  # Ignore out-of-order GPS ping
    if prev and prev['cell'] != new_cell:
        cell_index[prev['cell']].discard(driver_id)
    cell_index.setdefault(new_cell, set()).add(driver_id)
    driver_map[driver_id] = {'cell': new_cell, 'ts_ms': ts_ms}
